  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

let result = null;

for (let i = lines.length - 1; i >= 0; i--) {
  const line = lines[i];

  if (!line.startsWith("{") || !line.endsWith("}")) {
    continue;
  }

  try {
    const parsed = JSON.parse(line);

    if (
      parsed &&
      parsed.success === true &&
      parsed.media_path
    ) {
      result = parsed;
      break;
    }
  } catch (error) {}
}

if (!result) {
  throw new Error(
    "Could not find successful Reel JSON in output."
  );
}

return {
  json: {
    ...result,
    music_text: result.music_text || null,
    music_url: result.music_url || null
  }
};

const output = String($json.stdout || "");

const lines = output
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

let result = null;

// Find the final JSON object printed by fetch_lyrics.py
for (let i = lines.length - 1; i >= 0; i--) {
  const line = lines[i];

  if (!line.startsWith("{") || !line.endsWith("}")) {
    continue;
  }

  try {
    const parsed = JSON.parse(line);

    if (
      parsed &&
      parsed.success === true &&
      parsed.random_snippet
    ) {
      result = parsed;
      break;
    }
  } catch (error) {}
}

if (!result) {
  throw new Error(
    "Could not find successful lyrics JSON in Fetch Lyrics output."
  );
}


// Make sure the important fields exist
if (!result.artist || !result.title) {
  throw new Error(
    "Lyrics result is missing artist or title."
  );
}

if (!result.random_snippet) {
  throw new Error(
    "Lyrics result is missing random lyric snippet."
  );
}


// Return clean structured data
return {
  json: {
    success: true,

    artist: result.artist,
    title: result.title,

    song: {
      artist: result.artist,
      title: result.title
    },

    lyrics_source: result.source || "Tamil2Lyrics",
    lyrics_url: result.url || "",

    lyrics: result.lyrics || "",
    lyric_lines: result.lyric_lines || [],

    random_snippet: result.random_snippet,

    song_source: $json.song_source || null
  }
};

// ---------------------------------------------------------
// PREPARE OLLAMA REQUEST
// ---------------------------------------------------------

const title = String($json.song?.title || "").trim();
const artist = String($json.song?.artist || "").trim();
const lyric = String($json.random_snippet || "").trim();


// ---------------------------------------------------------
// VALIDATION
// ---------------------------------------------------------

if (!title) {
  throw new Error("Song title is missing.");
}

if (!artist) {
  throw new Error("Artist name is missing.");
}

if (!lyric) {
  throw new Error("Random lyric snippet is missing.");
}


// ---------------------------------------------------------
// OLLAMA REQUEST
// ---------------------------------------------------------

return {
  json: {
    model: "gemma3",
    stream: false,

    messages: [
      {
        role: "system",

        content:
          "You are an Instagram caption writer. " +
          "Write natural, human-sounding Instagram captions. " +
          "The provided lyric is copyrighted text supplied by the user. " +
          "You must reproduce the provided lyric exactly as given. " +
          "Never translate it, rewrite it, extend it, or invent additional lyrics. " +
          "Do not explain your answer."
      },

      {
        role: "user",

        content: `Create a short Instagram caption for this Reel.

Song: ${title}
Artist: ${artist}

Original lyric snippet:
${lyric}

Rules:
- Keep the lyric EXACTLY as provided.
- Keep the lyric in its original language.
- Do NOT translate the lyric.
- Do NOT rewrite the lyric.
- Do NOT add or invent any other lyrics.
- Use the provided lyric naturally in the caption.
- Write ONE short, natural, aesthetic Instagram caption.
- Make it sound like a real person wrote it.
- Do not sound promotional.
- Do not mention that you are an AI.
- Add 5 to 8 relevant hashtags.
- Hashtags should relate to the Reel, song, language, music, or mood.
- Do not explain your answer.

Return ONLY valid JSON in exactly this format:
{"caption":"your caption","hashtags":["#tag1","#tag2","#tag3"]}`
      }
    ]
  }
};

// Get the original Reel metadata from Parse Reel Result
const reel = $('Parse Reel Result').item.json;

// Get music information
const musicText = String(reel.music_text || "").trim();
const musicUrl = String(reel.music_url || "").trim();

const normalized = musicText.toLowerCase();

const genericAudioNames = [
  "original audio",
  "original sound",
  "original audio - instagram",
  "original sound - instagram"
];

const isGenericAudio =
  !musicText ||
  genericAudioNames.some(name => normalized.includes(name));

const instagramMusicAvailable =
  !isGenericAudio &&
  (
    musicUrl.includes("/reels/audio/") ||
    musicUrl.includes("/music/")
  );

return {
  json: {
    ...reel,

    // Keep the audio file information
    audio_path: "F:\\ReelAlchemy\\audio\\reel.wav",

    // Song detection information
    instagram_music_available: instagramMusicAvailable,

    song_source: instagramMusicAvailable
      ? "instagram"
      : "shazam"
  }
};

const musicText = String($json.music_text || "").trim();

if (!musicText) {
  throw new Error("Instagram music information is missing.");
}

// Instagram normally formats this as:
// Artist â€¢ Song Title
//
// Use the LAST bullet so multiple artists are preserved.
const separator = "â€¢";
const separatorIndex = musicText.lastIndexOf(separator);

if (separatorIndex === -1) {
  throw new Error(
    `Could not separate artist and title from Instagram music: ${musicText}`
  );
}

const artist = musicText
  .slice(0, separatorIndex)
  .trim();

const title = musicText
  .slice(separatorIndex + separator.length)
  .trim();

if (!artist || !title) {
  throw new Error(
    `Invalid Instagram music information: ${musicText}`
  );
}

return {
  json: {
    ...$json,

    song: {
      artist,
      title
    },

    song_source: "instagram"
  }
};

const output = String($json.stdout || "");

const lines = output
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

let result = null;

// Find the final JSON object printed by the Shazam script
for (let i = lines.length - 1; i >= 0; i--) {
  const line = lines[i];

  if (!line.startsWith("{") || !line.endsWith("}")) {
    continue;
  }

  try {
    const parsed = JSON.parse(line);

    if (parsed && typeof parsed.success === "boolean") {
      result = parsed;
      break;
    }
  } catch (error) {}
}

if (!result) {
  throw new Error("Could not find Shazam JSON result.");
}


// ---------------------------------------------------------
// SHAZAM FAILED
// ---------------------------------------------------------

if (result.success !== true) {
  throw new Error(
    result.error || "Song could not be identified by Shazam."
  );
}


// ---------------------------------------------------------
// SHAZAM SUCCEEDED
// ---------------------------------------------------------

const artist = String(
  result.artist ||
  result.artists ||
  result.subtitle ||
  ""
).trim();

const title = String(
  result.title ||
  result.track ||
  ""
).trim();


// Make sure both are available
if (!artist || !title) {
  throw new Error(
    "Shazam identified a result, but artist/title were missing."
  );
}


// ---------------------------------------------------------
// STANDARD SONG FORMAT
// This is the same structure used by Parse Instagram Song
// ---------------------------------------------------------

return {
  json: {
    success: true,
    song_identified: true,
    song_source: "shazam",

    song: {
      artist: artist,
      title: title
    }
  }
};

const content = String(
  $json.message?.content || ""
).trim();

if (!content) {
  throw new Error("Ollama returned empty content.");
}

// Remove Markdown code fences if Ollama wrapped the JSON in ```json ... ```
const cleaned = content
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let result;

try {
  result = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `Could not parse Ollama JSON: ${error.message}\n\nOllama response:\n${content}`
  );
}

if (!result.caption) {
  throw new Error("Ollama response is missing caption.");
}

if (!Array.isArray(result.hashtags)) {
  throw new Error("Ollama response is missing hashtags array.");
}

// Clean hashtags:
// "#AR Rahman" â†’ "#ARRahman"
// Remove whitespace and keep only actual hashtags.
const hashtags = result.hashtags
  .map(tag => String(tag).trim())
  .map(tag => tag.replace(/\s+/g, ""))
  .filter(tag => tag.startsWith("#"));

if (hashtags.length === 0) {
  throw new Error("Ollama returned no valid hashtags.");
}

const caption = String(result.caption).trim();

return {
  json: {
    caption,
    hashtags,

    full_caption:
      caption +
      "\n\n" +
      hashtags.join(" ")
  }
};

const ollama = $json;

const lyrics = $('Parse Lyrics').item.json;
const reel = $('Parse Reel Result').item.json;

const caption = String(ollama.caption || "").trim();

const hashtags = Array.isArray(ollama.hashtags)
  ? ollama.hashtags.map(tag => String(tag).trim()).filter(Boolean)
  : [];

const fullCaption = String(
  ollama.full_caption ||
  (
    caption +
    "\n\n" +
    hashtags.join(" ")
  )
).trim();

const artist = String(
  lyrics.song?.artist || ""
).trim();

const title = String(
  lyrics.song?.title || ""
).trim();

const lyric = String(
  lyrics.random_snippet || ""
).trim();

if (!caption) {
  throw new Error("Final caption is missing.");
}

if (!artist) {
  throw new Error("Artist is missing.");
}

if (!title) {
  throw new Error("Song title is missing.");
}

if (!lyric) {
  throw new Error("Random lyric snippet is missing.");
}

if (!reel.reel_url) {
  throw new Error("Reel URL is missing.");
}

return {
  json: {
    ready_to_post: true,

    reel: {
      url: reel.reel_url,
      media_path: reel.media_path || ""
    },

    song: {
      title,
      artist,
      source: lyrics.song_source || null
    },

    lyrics: {
      snippet: lyric,
      source: lyrics.lyrics_source || "",
      url: lyrics.lyrics_url || ""
    },

    caption,

    hashtags,

    full_caption: fullCaption,

    edit_caption: fullCaption
  }
};

const caption = String(
  $json.full_caption || ""
);

if (!caption.trim()) {
  throw new Error("full_caption is empty.");
}

return {
  json: {
    ...$json,

    caption_base64:
      Buffer
        .from(caption, "utf8")
        .toString("base64")
  }
};
